import{z as A,x as d,o as s,c as p,q as l,j as o,D as E,d as e,s as n,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"BST 删除与后继","description":"","frontmatter":{"title":"BST 删除与后继","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bst-delete.md","filePath":"cs/bst-delete.md","lastUpdated":1791063341000}'),B={name:"cs/bst-delete.md"};function c(h,a,m,D,T,u){const r=d("Mermaid");return s(),p("div",null,[a[2]||(a[2]=l('<h1 id="bst-删除与后继" tabindex="-1">BST 删除与后继 <a class="header-anchor" href="#bst-删除与后继" aria-label="Permalink to &quot;BST 删除与后继&quot;">​</a></h1><div class="epigraph"><p>有两个孩子的节点不能直接剪掉；中序后继顶上去，查找树的左右序才还在。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 第 12 章；Knuth, TAOCP 卷 3 整理</footer></div><p><a href="/cs/bst">上一课</a>钉了 BST 不变式、查找与插入，并承认删除分三支、双子要找后继，却未把后继与拼接写完。本课不重讲「小走左、大走右」。缺口是删除保持中序序列：叶与单子是改一条边；双子用后继（或前驱）的键顶替，再删后继——后继最多一个孩子。平衡仍不进场；最坏仍可成链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>删叶：父的对应孩子置空。删只有一棵子树的节点：父改接到那棵子树。删两个孩子的 \\(z\\)：若直接把左右子树随便挂到父上，中间那些键与 \\(z\\) 的父的序会乱。缺口不是旋转，而是<strong>中序后继 \\(y\\)：右子树中最小，即从右孩子一路向左</strong>。\\(y\\) 没有左孩子。把 \\(y\\) 的键写入 \\(z\\)（或把 \\(y\\) 摘下接到 \\(z\\) 的位置），再按单子情况删 \\(y\\) 的原位。</p><p>后继也是「下一个更大键」查询的实现，字典合同需要它，不只为删除。</p><p><span class="marginnote">用前驱（左子树最大）对称。实现选一侧即可；后课 AVL 删除同样先做 BST 删除再旋转。</span></p><p><span class="marginnote">数字实例：树为根 30，左孩子 20，右孩子 40（40 只有右孩子 50）。删根 30：后继是右子树最小 = 40。把 40 写进根节点，再删原 40 节点——它只有右孩子，父节点直接收养 50。结果根 40、左 20、右 50，中序仍是 20, 40, 50，全程只动了常数条指针。</span></p><p>下图回答一个具体问题：拿到待删节点 \\(z\\) 时，按孩子数走哪条路。</p>',9)),(s(),o(i,null,{default:E(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%7B%22z%20%E6%9C%89%E5%87%A0%E4%B8%AA%E5%AD%A9%E5%AD%90%EF%BC%9F%22%7D%20--%3E%7C%22%E9%9B%B6%E4%B8%AA%EF%BC%9A%E5%8F%B6%22%7C%20L%5B%22%E7%88%B6%E7%9A%84%E5%AF%B9%E5%BA%94%E6%8C%87%E9%92%88%E7%BD%AE%E7%A9%BA%22%5D%0A%20%20Z%20--%3E%7C%22%E4%B8%80%E4%B8%AA%22%7C%20O%5B%22%E7%88%B6%E7%9B%B4%E6%8E%A5%E6%94%B9%E6%8E%A5%E9%82%A3%E6%A3%B5%E5%AD%90%E6%A0%91%22%5D%0A%20%20Z%20--%3E%7C%22%E4%B8%A4%E4%B8%AA%22%7C%20T%5B%22%E5%8F%96%E5%8F%B3%E5%AD%90%E6%A0%91%E6%9C%80%E5%B0%8F%20y%20%E9%A1%B6%E6%9B%BF%20z%20%E7%9A%84%E9%94%AE%22%5D%0A%20%20T%20--%3E%20YD%5B%22%E5%86%8D%E6%8C%89%E5%8D%95%E5%AD%90%E6%88%96%E5%8F%B6%E5%88%A0%E9%99%A4%20y%20%E5%8E%9F%E4%BD%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"方法",tabindex:"-1"},[e("方法 "),t("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[4]||(a[4]=t("p",null,[t("code",null,"Tree-Successor(x)"),e("：若 "),t("code",null,"x.right"),e(" 非空，沿左下到尽头；否则沿父上走，直到自己是左孩子。无父指针则删除时从根一路记下路径，或在找 \\(z\\) 时同时找后继。")],-1)),(s(),o(i,null,{default:E(()=>[n(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%88%A0%20z%EF%BC%8C%E4%B8%A4%E5%AD%90%E9%9D%9E%E7%A9%BA%22%5D%20--%3E%20Y%5B%22y%20%3D%20%E5%8F%B3%E5%AD%90%E6%A0%91%E6%9C%80%E5%B0%8F%22%5D%0A%20%20Y%20--%3E%20COPY%5B%22z%20%E7%9A%84%E9%94%AE%20%E2%86%90%20y%20%E7%9A%84%E9%94%AE%22%5D%0A%20%20COPY%20--%3E%20DELY%5B%22%E6%8C%89%E5%8D%95%E5%AD%90%E5%88%A0%E9%99%A4%20y%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>卫星数据：若卫星跟着键走，复制键时要复制卫星，或改指针拓扑使 \\(y\\) 节点占据 \\(z\\) 的位置，避免大对象拷贝。不变式只关心键序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一次删除 \\(O(h)\\) 步：查找 \\(z\\)、找 \\(y\\)、改常数指针。\\(h\\) 无界时与查找同病。删除不自动降低最坏高度——删叶甚至可能让链更「瘦」但仍是链。这是 AVL 课的动机：旋转在删后恢复高度差。</p><p>与链表删除不同：BST 不能只靠 <code>prev/next</code> 绕过，除非另维护中序线索；标准树上后继可能要上爬。</p><p><span class="marginnote">直觉类比：双子删除像辞退中层主管 \\(z\\)。不能让他的两个下属直接归大老板管（汇报线会乱），而是让接班人 \\(y\\)——右班里资历最浅的那位（右子树最小键）——顶到 \\(z\\) 的位置，\\(y\\) 留下的空位再按普通离职手续（叶/单子）交接。注意全程 \\(z\\) 的左右子树都不搬家。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入惰性删除（只打标记），不处理重复键的哪一个被删。也不把红黑的双黑修复写进来。父指针可选；CLRS 用父指针写 successor。</p><p>后课默认：BST 删除保持中序；双子走后继。高度仍无保证，必须平衡。</p><p><span class="marginnote">常见误区：初学者以为双子删除要把整棵子树搬走重挂。实际上只移动一个键（或一个节点 \\(y\\)）：\\(y\\) 本来就在 \\(z\\) 的右子树内且无左孩子，把它摘下接走不影响其余任何键的相对次序，中序序列自然保持。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>叶/单子改指针；双子用中序后继顶替再删后继。</li><li>后继 = 右子最小，或沿父上爬。</li><li>复杂度 \\(\\Theta(h)\\)；下一课 AVL 用旋转钉 \\(h=\\Theta(\\log n)\\)。</li><li>出处：Cormen et al. 第 12.3 节；Knuth, <em>TAOCP</em> 卷 3。</li></ul>',11))])}const f=A(B,[["render",c]]);export{_ as __pageData,f as default};
